    /\ munch [(lo, bv_unsigned sp); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
