  ACONST m -> stack0 m lo shi -> bv_unsigned sp + 320 <= shi -> bv_unsigned sp mod 32 = 0 ->     (* [comment removed for export] *)
  mem_inv bsegs m -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (dof_lam_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc C E lo shi m)
